```python
def solve(s):
    """You are given a string s.
    if s[i] is a letter, reverse its case from lower to upper or vise versa, 
    otherwise keep it as it is.
    If the string contains no letters, reverse the string.
    The function should return the resulted string.
    """
    if any(ch.isalpha() for ch in s):
        return s.swapcase()
    return s[::-1]
```

```python
def intersection(interval1, interval2):
    a, b = interval1
    c, d = interval2

    # intersection interval [start, end]
    start = max(a, c)
    end = min(b, d)
    if start > end:
        return "NO"

    length = end - start  # closed intervals: length = end - start
    if length < 2:
        return "NO"

    import math
    n = length
    if n % 2 == 0:
        return "YES" if n == 2 else "NO"
    limit = int(math.isqrt(n))
    for i in range(3, limit + 1, 2):
        if n % i == 0:
            return "NO"
    return "YES"
```

```python
def select_words(s, n):
    vowels = "aeiouAEIOU"
    result = []
    for word in s.split():
        count = 0
        for ch in word:
            if ch.isalpha() and ch not in vowels:
                count += 1
        if count == n:
            result.append(word)
    return result
```

```python
def compare_one(a, b):
    """
    Compare two values that may be ints, floats, or strings representing real numbers.
    Returns the larger value in its original type, or None if they are equal.

    The string representation may use '.' or ',' as the decimal separator.
    """
    def to_float(x):
        if isinstance(x, (int, float)):
            return float(x)
        if isinstance(x, str):
            # Normalise decimal separator
            normalized = x.replace(',', '.')
            return float(normalized)
        raise TypeError("Unsupported type")

    val_a = to_float(a)
    val_b = to_float(b)

    if val_a == val_b:
        return None
    return a if val_a > val_b else b
```

```python
def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    def to_float(x):
        if isinstance(x, str):
            return float(x.replace(",", "."))
        return float(x)

    fa, fb = to_float(a), to_float(b)

    if fa > fb:
        return a
    elif fb > fa:
        return b
    else:
        return None
```

```python
def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    drops = 0
    for i in range(n):
        if arr[i] > arr[(i + 1) % n]:
            drops += 1
            if drops > 1:
                return False
    return True
```

```python
def move_one_ball(arr):
    if len(arr) == 0:
        return True

    n = len(arr)
    break_count = 0

    for i in range(n):
        if arr[i] > arr[(i + 1) % n]:
            break_count += 1

    return break_count <= 1
```

```python
def tri(n):
    seq = [0] * (n + 1)
    if n >= 0:
        seq[0] = 1
    for i in range(1, n + 1):
        if i == 1:
            seq[i] = 3
        elif i % 2 == 0:
            seq[i] = 1 + i / 2
        else:
            next_val = 1 + (i + 1) / 2
            seq[i] = seq[i - 1] + seq[i - 2] + next_val
    return seq
```

```python
def count_nums(arr):
    def digits_sum(n):
        neg = n < 0
        n = abs(n)
        digits = [int(d) for d in str(n)]
        if neg:
            digits[0] = -digits[0]
        return sum(digits)

    return len([n for n in arr if digits_sum(n) > 0])
```
